 static int32_t find_previous_index(
     const float array[],
     int32_t size,
     float value
 )
 {
     int32_t start = 0;
     int32_t end = size - 1;
     int32_t result = -1;

     while (start <= end)
     {
         int32_t mid =
             start + (end - start) / 2;

         if (array[mid] < value)
         {
             result = mid;
             start = mid + 1;
         }
         else
         {
             end = mid - 1;
         }
     }

     return result;
 }
 
 float breath_reference_get_volume(
     float respiratory_rate_bpm,
     float tidal_volume_ml,
     float time_s
 )
 {
     if (respiratory_rate_bpm <= 0.0f)
     {
         return 0.0f;
     }

     const float total_period_s =
         60.0f / respiratory_rate_bpm;

     /*
      * Posición temporal dentro del ciclo respiratorio.
      */
     const float cycle_time_s =
         fmodf(time_s, total_period_s);

     /*
      * Escalamos ese tiempo al eje temporal
      * de la curva de referencia.
      */
     const float reference_time_s =
         cycle_time_s *
         reference.max_time_s /
         total_period_s;

     int32_t index =
         find_previous_index(
             reference.time_s,
             reference.size,
             reference_time_s
         );


     /*
      * Antes del primer punto.
      */
     if (index < 0)
     {
         return tidal_volume_ml *
                reference.volume_ml[0] /
                reference.max_volume_ml;
     }


     /*
      * Después del último punto.
      */
     if (index >= reference.size - 1)
     {
         return tidal_volume_ml *
                reference.volume_ml[
                    reference.size - 1
                ] /
                reference.max_volume_ml;
     }


     /*
      * Interpolación lineal entre las dos
      * muestras vecinas.
      */

     const float t0 =
         reference.time_s[index];

     const float t1 =
         reference.time_s[index + 1];

     const float v0 =
         reference.volume_ml[index];

     const float v1 =
         reference.volume_ml[index + 1];

     const float interpolation =
         (reference_time_s - t0) /
         (t1 - t0);

     const float reference_volume_ml =
         v0 + (v1 - v0) * interpolation;


     /*
      * Escalamos la curva al VT solicitado.
      */
     return (tidal_volume_ml * reference_volume_ml / reference.max_volume_ml);
 }